function sanitizeCell(val) {
  if (val === null || val === undefined) return '';
  var s = String(val);
  if (/^[=+\-@\t\r]/.test(s)) {
    return "'" + s;
  }
  return s;
}

function appendRows(sheetName, headers, records) {
  const sheet = getOrCreateSheet(sheetName, headers);
  const rows = records.map(function(r) {
    return headers.map(function(h) {
      return sanitizeCell(r[h]);
    });
  });
  if (rows.length > 0) {
    sheet.getRange(sheet.getLastRow() + 1, 1, rows.length, headers.length).setValues(rows);
  }
}

var ALLOWED_ROUTES = ['國道1號', '國道3號', '國道4號', '國道5號', '國道6號', '國道8號', '國道10號'];
var ALLOWED_DIRECTIONS = ['北上', '南下', '東向', '西向', '順向', '逆向'];

function validateRoute(r) {
  return ALLOWED_ROUTES.indexOf(r) !== -1 ? r : '其他路線';
}

function isAuthorized(e) {
  if (!API_SECRET || API_SECRET.trim().length === 0) {
    console.error('API_SECRET is not configured in ScriptProperties');
    return false;
  }
  return e && e.parameter && e.parameter.key === API_SECRET;
}

// Replace static secret parameter with OAuth Bearer token or backend session auth
function buildUrl(base: string, params: Record<string, string> = {}): string {
  const u = new URL(base);
  Object.entries(params).forEach(([k, v]) => u.searchParams.set(k, v));
  return u.toString();
}
